// ──────────────────────────────────────────────────────────────────────────────
// Classifier Function
// ──────────────────────────────────────────────────────────────────────────────
// Accepts:  title, url, metaDesc (optional), metaKeywords (optional)
// Returns:  category name string
// ──────────────────────────────────────────────────────────────────────────────

function _bkCategorize(title, url, metaDesc, metaKeywords) {
  const urlLower = (url || '').toLowerCase();

  // ── Phase 1: URL-domain matching (highest confidence) ──
  for (const rule of _BK_CAT_RULES) {
    if (rule.re.test(urlLower)) return rule.name;
  }

  // ── Phase 2: Title + Meta fallback (keyword-based) ──
  const combo = [
    (title || ''),
    (metaDesc || ''),
    (metaKeywords || '')
  ].join(' ').toLowerCase();

  for (const rule of _BK_TITLE_RULES) {
    if (rule.re.test(combo)) return rule.name;
  }

  return 'Other';
}